/// <summary>
/// Researches and returns the position of the form data source.
/// </summary>
/// <param name = "_common"> The common record object.</param>
/// <returns> The current record position.</returns>
public static int getRecordPosition(Common _common)
{
    int recordPosition = 0;

    if (FormDataUtil::isFormDataSource(_common))
    {
        recordPosition = FormDataUtil::getFormDataSource(_common).getPosition();
    }

    return recordPosition;
}

/// <summary>
/// Researches and sets the position of the form data source to the specified record position.
/// </summary>
/// <param name = "_common"> The common record object.</param>
/// <param name = "_recordPosistion"> The desired record position.</param>
public static void researchAndSetPos(Common _common, int _recordPosistion)
{
    if (FormDataUtil::isFormDataSource(_common))
    {
        FormDataUtil::getFormDataSource(_common).research(false);

        if (_recordPosistion > 0)
        {
            FormDataUtil::getFormDataSource(_common).setPosition(_recordPosistion);
        }
    }
}
